#!/usr/bin/env bash
# Deploys tests/fixtures/Deadline.sol with a one-week window and leaves its address where the
# phase's script can find it. Nothing here can be exercised without moving the chain's clock.
set -eu

SENDER=0x00000000000000000000000000000000000003ea

WINDOW=$(printf '%064x' 604800)

rpc() {
  curl -s -X POST "$HANVIL_RPC_URL" -H 'content-type: application/json' -d "$1"
}

hash=$(rpc "{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"eth_sendTransaction\",\"params\":[{\"from\":\"$SENDER\",\"data\":\"${INIT}${WINDOW}\"}]}" \
  | sed -n 's/.*"result":"\(0x[0-9a-f]*\)".*/\1/p')
test -n "$hash" || { echo "deploy was refused" >&2; exit 1; }

address=$(rpc "{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"eth_getTransactionReceipt\",\"params\":[\"$hash\"]}" \
  | sed -n 's/.*"contractAddress":"\(0x[0-9a-fA-F]*\)".*/\1/p')
test -n "$address" || { echo "no contract address in the receipt" >&2; exit 1; }

printf '%s\n' "$address" > .harness/deadline-address
echo "Deadline deployed at $address, open for 604800 s"
